    add(list, cyl(0.5, 0.5, 1.2, 8), 0x3d4238, [6.8, 0.6, 1.0])
    add(list, cyl(0.5, 0.5, 1.2, 8), 0x3d4238, [6.8, 0.6, 2.2])
