  // mergeGeometries is imported lazily to keep menu startup light
  const { mergeGeometries } = THREE.__mergeUtils || {}
  if (!mergeGeometries) throw new Error('merge utils missing')
  return mergeGeometries(list, false)
}

let mergeUtilsPromise = null
async function ensureMergeUtils() {
  if (!mergeUtilsPromise) {
    mergeUtilsPromise = import('three/addons/utils/BufferGeometryUtils.js').then(m => {
      THREE.__mergeUtils = m
      return m
    })
  }
  return mergeUtilsPromise
}

