267:     let cost = s.cost;
268:     if (mods.unitCost) cost *= mods.unitCost;
269:     if (mods.vehicleCost && ['scout', 'tank', 'heavy', 'artillery', 'harvester'].includes(type)) cost *= mods.vehicleCost;
270:     if (mods.infCost && ['rifle', 'engineer', 'at'].includes(type)) cost *= mods.infCost;
271:     s.cost = Math.round(cost / 5) * 5;
272:   }
273:   if (base.time > 0) {
274:     let time = s.time;
275:     if (mods.vehicleTime && ['scout', 'tank', 'heavy', 'artillery', 'harvester'].includes(type)) time *= mods.vehicleTime;
276:     s.time = time;
277:   }
278:   if (mods.infHp && base.armor === 'infantry') s.hp *= mods.infHp;
279:   if (mods.vehicleHp && base.armor !== 'infantry') s.hp *= mods.vehicleHp;
280:   if (mods.vehicleDmg && base.weapon === 'shell') s.dmg *= mods.vehicleDmg;
281:   if (mods.vision) s.vision *= mods.vision;
282:   if (mods.speed) s.speed *= mods.speed;
283:   if (mods.vehicleSpeed && base.armor !== 'infantry') s.speed *= mods.vehicleSpeed;
284:   s.hp = Math.round(s.hp);
285:   s.dmg = Math.round(s.dmg);
286:   s.speed = Math.round(s.speed * 10) / 10;
